window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1bf799a475392c26"]={"versions": [{"id": "FIG-1bf799a475392c26", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR FlexRay Transportprotokolls (FrTp). Es stellt den protokollarischen Nachrichtenaustausch für eine unsegmentierte 1:1-Punkt-zu-Punkt-Übertragung bei konfigurierter Quittierung mit Wiederholungsversuch (Acknowledgement with Retry) im positiven Erfolgsfall dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende Instanz bzw. Quell-Knoten des FlexRay Transportprotokolls (FrTp).\n</li><li><strong>Receiver</strong>: Empfangende Instanz bzw. Ziel-Knoten des FrTp.\n</li><li><strong>SF (Single Frame)</strong>: Unsegmentierte Protokolldateneinheit (N-PDU) zur Übertragung von Nutzdaten in einem einzelnen FlexRay-Frame vom Sender zum Receiver.\n</li><li><strong>AF (Positive Acknowledge)</strong>: Quittierungs-Rahmen (Acknowledgement Frame), der vom Receiver zum Sender zurückgesendet wird, um den fehlerfreien Empfang des Single Frames positiv zu bestätigen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Datenübertragung durch das Absenden eines Single Frames (<code>SF</code>) an den Receiver.\n</li><li>Der Receiver nimmt den <code>SF</code> entgegen, verarbeitet die Nutzdaten erfolgreich und generiert einen Quittierungsrahmen.\n</li><li>Der Receiver sendet den Quittierungsrahmen mit positiver Rückmeldung (<code>AF (Positive Acknowledge)</code>) an den Sender zurück.\n</li><li>Nach dem Empfang der positiven Quittung schließt der Sender die Übertragung ohne Auslösung eines Wiederholungsversuchs (Retry) erfolgreich ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt den Gutfall der unsegmentierten Übertragung im FrTp-Modus mit konfigurierter Quittierung. Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Für Quittierungen mit Retry ist senderseitig bei Übertragung des <code>SF</code> ein Quittierungstimer zu starten, der mit Empfang des <code>AF (Positive Acknowledge)</code> gestoppt wird.\n</li><li>Bleibt das <code>AF</code> aus oder meldet einen Fehler, greift der konfigurierte Retry-Mechanismus; im dargestellten Erfolgsfall wird der Puffer direkt nach Eingang des positiven <code>AF</code> freigegeben und der übergeordnete PDU-Router über den erfolgreichen Abschluss informiert.\n</li><li>Die N-PDU-Parameter für <code>SF</code> und <code>AF</code> müssen bezüglich Verbindungs-ID und Adressierung zueinander passend konfiguriert sein.\n</li></ul>"}, {"id": "FIG-ec62814d998ef9c5", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR FlexRay Transportprotokolls (FrTp). Es stellt den protokollarischen Nachrichtenaustausch für eine unsegmentierte 1:1-Punkt-zu-Punkt-Übertragung bei konfigurierter Quittierung mit Wiederholungsversuch (Acknowledgement with Retry) im positiven Erfolgsfall dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende Instanz bzw. Quell-Knoten des FlexRay Transportprotokolls (FrTp).\n</li><li><strong>Receiver</strong>: Empfangende Instanz bzw. Ziel-Knoten des FrTp.\n</li><li><strong>SF (Single Frame)</strong>: Unsegmentierte Protokolldateneinheit (N-PDU) zur Übertragung von Nutzdaten in einem einzelnen FlexRay-Frame vom Sender zum Receiver.\n</li><li><strong>AF (Positive Acknowledge)</strong>: Quittierungs-Rahmen (Acknowledgement Frame), der vom Receiver zum Sender zurückgesendet wird, um den fehlerfreien Empfang des Single Frames positiv zu bestätigen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Datenübertragung durch das Absenden eines Single Frames (<code>SF</code>) an den Receiver.\n</li><li>Der Receiver nimmt den <code>SF</code> entgegen, verarbeitet die Nutzdaten erfolgreich und generiert einen Quittierungsrahmen.\n</li><li>Der Receiver sendet den Quittierungsrahmen mit positiver Rückmeldung (<code>AF (Positive Acknowledge)</code>) an den Sender zurück.\n</li><li>Nach dem Empfang der positiven Quittung schließt der Sender die Übertragung ohne Auslösung eines Wiederholungsversuchs (Retry) erfolgreich ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt den Gutfall der unsegmentierten Übertragung im FrTp-Modus mit konfigurierter Quittierung. Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Für Quittierungen mit Retry ist senderseitig bei Übertragung des <code>SF</code> ein Quittierungstimer zu starten, der mit Empfang des <code>AF (Positive Acknowledge)</code> gestoppt wird.\n</li><li>Bleibt das <code>AF</code> aus oder meldet einen Fehler, greift der konfigurierte Retry-Mechanismus; im dargestellten Erfolgsfall wird der Puffer direkt nach Eingang des positiven <code>AF</code> freigegeben und der übergeordnete PDU-Router über den erfolgreichen Abschluss informiert.\n</li><li>Die N-PDU-Parameter für <code>SF</code> und <code>AF</code> müssen bezüglich Verbindungs-ID und Adressierung zueinander passend konfiguriert sein.\n</li></ul>"}], "trans": [{"from": "FIG-1bf799a475392c26", "to": "FIG-ec62814d998ef9c5", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
